    // Without this, the eviction iterator holds a dangling folio pointer
    // in main_list, causing kernel memory corruption (GPF in userspace).
    bpf_cache_ext_list_del(folio);

    u64 key = (u64)folio;
    bpf_map_delete_elem(&folio_metadata_map, &key);

